-- Generated by `npm run seed:sql` from src/data/seedItems.js — do not edit by hand.
on conflict (slug) do update set
  type = excluded.type,
  name = excluded.name,
  description = excluded.description,
  image_url = coalesce(excluded.image_url, public.brand_items.image_url),
  data = excluded.data,
  display_order = excluded.display_order,
  round = excluded.round,
  updated_at = now();
